package io.github.hemanthvk980.shortener.web;

import io.github.hemanthvk980.shortener.domain.Link;
import io.github.hemanthvk980.shortener.service.LinkService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.net.URI;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/links")
public class LinkController {
    public record CreateLinkRequest(@NotBlank String url) {}

    public record LinkResponse(String code, String shortUrl, String targetUrl) {}

    private final LinkService service;
    private final String baseUrl;

    public LinkController(LinkService service, @Value("${app.base-url}") String baseUrl) {
        this.service = service;
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl : baseUrl + "/";
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody CreateLinkRequest req) {
        Link l = service.create(req.url());
        return ResponseEntity.created(URI.create("/api/v1/links/" + l.getCode()))
                .body(new LinkResponse(l.getCode(), baseUrl + l.getCode(), l.getTargetUrl()));
    }

    @GetMapping("/{code}/stats")
    public Map<String, Object> stats(@PathVariable String code) {
        Link l = service.resolve(code);
        List<?> daily = service.daily(l);
        return Map.of("code", code, "totalClicks", l.getClickCount(), "clicksByDay", daily);
    }

    @ExceptionHandler(IllegalArgumentException.class)
    ProblemDetail badRequest(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }

    @ExceptionHandler(NoSuchElementException.class)
    ProblemDetail notFound(NoSuchElementException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }
}
